        return str(getattr(flag_option, "name", flag_option))

    @staticmethod
    def _arg_of(flag_option):
        for attr in ("get_arg", "get_option_arg"):
            if hasattr(flag_option, attr):
                return getattr(flag_option, attr)()
        for attr in ("option_arg", "arg"):
            if hasattr(flag_option, attr):
                return getattr(flag_option, attr)
        return None
